SELECT b.id,b.category_id,b.name,b.aliases,b.tags,b.summary,b.cover_url,b.sort_no,c.category_code,c.category_name

ORDER BY b.sort_no ASC, b.id ASC
LIMIT #{limit} OFFSET #{offset}

SELECT b.id,b.category_id,b.name,b.aliases,b.tags,b.summary,b.cover_url,b.sort_no,c.category_code,c.category_name
FROM encyclopedia_breed b
JOIN encyclopedia_category c ON c.id=b.category_id AND c.status='ENABLED'
WHERE b.status='PUBLISHED' AND b.category_id=#{categoryId} AND b.id<>#{excludeBreedId}
ORDER BY b.sort_no ASC, b.id ASC
LIMIT #{limit}
